# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::LocalOwner::ServiceAccess do
  it "service access refuses a missing caller, a user, an ungranted service and another company's service in that order" do
    actor_class = Timekeeping::LocalOwner::Actor
    granted = %w[reservations.prepare reservations.commit reservations.abort invoices.mark_billed agents.detach_entries]

    # "A nil actor answers `unauthorized`. A user actor, or a service without the operation, answers `forbidden`.
    # A service bound to another company answers `not_found`."
    expect(described_class.decide(actor: nil, company_id: 1, route: :prepare)).to eq(:unauthorized)
    expect(described_class.decide(actor: actor_class.user(user_id: 7, role: "owner"), company_id: 1, route: :prepare))
      .to eq(:forbidden)
    expect(described_class.decide(actor: actor_class.service(name: "reporting", company_id: 1, operations: []),
                                  company_id: 1, route: :mark_billed)).to eq(:forbidden)
    # A grant for one operation does not open another route.
    expect(described_class.decide(actor: actor_class.service(name: "invoice-boundary", company_id: 1,
                                                             operations: ["reservations.prepare"]),
                                  company_id: 1, route: :detach_entries)).to eq(:forbidden)
    # An ungranted service of another company is still forbidden: the grant is checked before the company.
    expect(described_class.decide(actor: actor_class.service(name: "reporting", company_id: 2, operations: []),
                                  company_id: 1, route: :prepare)).to eq(:forbidden)
    expect(described_class.decide(actor: actor_class.service(name: "invoice-boundary", company_id: 2, operations: granted),
                                  company_id: 1, route: :prepare)).to eq(:not_found)
    %i[prepare commit abort mark_billed detach_entries].each do |route|
      expect([route, described_class.decide(actor: actor_class.service(name: "invoice-boundary", company_id: 1,
                                                                       operations: granted),
                                            company_id: 1, route:)]).to eq([route, :allowed])
    end
  end

  it "service access grants only operations named in the shared background operations list" do
    expect(described_class::ROUTE_OPERATIONS.values - TimekeepingRules::EntryRules::BACKGROUND_OPERATIONS).to eq([])
  end

  it "local owner still refuses an operation it does not know" do
    expect {
      Timekeeping::LocalOwner.call(operation: :reserve_everything, company_id: 1, generation: "1", actor: nil, params: {})
    }.to raise_error(ArgumentError)
  end
end
